// ============ CONFIG RÉSONANCE — à remplir, identique dans les 7 workflows d'agents ============
return [{ json: {
  pipeline: "Prospection Résonance",          // nom exact du pipeline Pipedrive
  gemini_model: "gemini-flash-latest, gemini-flash-lite-latest", // un ou plusieurs modèles Google AI Studio, séparés par des virgules (répartition de la charge)
  pipedrive_base: "https://api.pipedrive.com/v1",
  gemini_base: "https://generativelanguage.googleapis.com/v1beta",
  gmail_base: "https://gmail.googleapis.com/gmail/v1/users/me",
  signataire: "Prénom Nom",                    // personne qui signe les emails
  emails_fondatrices: "",                      // adresses qui reçoivent alertes, arbitrage du lundi et export (séparées par des virgules ; vide = la boîte connectée)
  lien_rdv: "COLLER_ICI_LE_LIEN_DE_PRISE_DE_RENDEZ-VOUS",
  plafond_hebdo: 35,                           // premiers messages par semaine au maximum
  // Veille (agent 1)
  flux_rss: [ "COLLER_ICI_UNE_URL_DE_FLUX_RSS" ], // par exemple des flux Google Alertes
  label_veille: "veille",                      // libellé Gmail des newsletters et alertes à analyser
  fenetre_heures: 48,                          // âge maximal d'un article RSS
  max_articles: 25,
  // Bibliothèque de preuves validée par les fondatrices.
  // origine « À valider » = bloque le brouillon ; une phrase entre crochets est aussi bloquée par le contrôle automatique.
  preuves: [
    { id: "vins", segment: "Vins & Spiritueux", origine: "Projet Anna & Louise", phrase: "[Phrase de preuve validée : projet réalisé pour une maison de ce segment]" },
    { id: "beaute", segment: "Beauté & Parfumerie", origine: "Projet Anna & Louise", phrase: "[Phrase de preuve validée : projet réalisé pour une maison de ce segment]" },
    { id: "joaillerie", segment: "Joaillerie & Horlogerie", origine: "Expérience des fondatrices (autre structure)", phrase: "[Phrase de preuve validée : expérience antérieure des fondatrices]" },
    { id: "mode", segment: "Mode & Maroquinerie", origine: "À valider", phrase: "[Phrase de preuve en attente de validation]" }
  ],
  // Emails des fondatrices ou de l'agence ayant obtenu une réponse (modèles de style de l'agent 4)
  exemples_valides: []
}}];

// Carte des champs et étapes Pipedrive, retrouvés par leur NOM exact
const cfg = $('CONFIG').first().json;
const n = s => String(s || '').trim();
const dealF = $('Champs affaires').first().json.data || [];
const persF = $('Champs personnes').first().json.data || [];
const stages = ($('Étapes').first().json.data || []).filter(s => n(s.pipeline_name) === cfg.pipeline);
const perso = f => /^[0-9a-f]{40}$/.test(f.key);   // champ personnalisé (prioritaire sur un champ système du même nom)
const map = arr => Object.fromEntries([...arr.filter(f => !perso(f)), ...arr.filter(perso)].map(f => [n(f.name), f.key]));
const deal = map(dealF), person = map(persF);
const stage = Object.fromEntries(stages.map(s => [n(s.name), s.id]));

const requis = {
  deal: ['Type de signal','URL source','Date de publication','Extrait source','Résumé du signal','Catégorie','Taille budget',"Porte d'entrée",'Adéquation expertises','Fait vérifié','Hypothèse','Preuve A&L','Score Résonance','Détail du score','Motif du score','Niveau','Angle','Prochaine action','Activer','Discrétion IA','Brouillon généré','Texte du dernier message','Date premier envoi','Nb relances','Tâche LinkedIn','Reprise le','Date de réactivation','Motif de refus','Fin de conservation'],
  person: ['Civilité','Poste','Niveau de décision','Opposition','Provenance coordonnées','Fiabilité email'],
  stage: ['À rechercher','À qualifier','Prêt à contacter','Contacté','À relancer','Conversation ouverte','Rendez-vous','En pause']
};
const manquants = [
  ...requis.deal.filter(x => !deal[x]).map(x => 'champ affaire « ' + x + ' »'),
  ...requis.person.filter(x => !person[x]).map(x => 'champ personne « ' + x + ' »'),
  ...requis.stage.filter(x => !stage[x]).map(x => 'étape « ' + x + ' » du pipeline « ' + cfg.pipeline + ' »')
];
if (manquants.length) throw new Error('À créer dans Pipedrive (noms exacts) : ' + manquants.join(', '));
return [{ json: { deal, person, stage, pipeline_id: stages[0].pipeline_id } }];

const norm = s => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();
const val = (obj, key) => { const v = obj ? obj[key] : undefined; return (v && typeof v === 'object' && 'value' in v) ? v.value : v; };
const today = () => new Date().toISOString().slice(0, 10);
const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const pdDate = s => s ? new Date(String(s).replace(' ', 'T') + (String(s).includes('Z') || String(s).length <= 10 ? '' : 'Z')) : null;
const ouvres = (from, to = new Date()) => { if (!from) return 0; let n = 0; const d = new Date(from); d.setUTCHours(12, 0, 0, 0); const e = new Date(to); while (true) { d.setUTCDate(d.getUTCDate() + 1); if (d > e) break; const w = d.getUTCDay(); if (w !== 0 && w !== 6) n++; } return n; };
const plusOuvres = (from, k) => { const d = new Date(from); let n = 0; while (n < k) { d.setUTCDate(d.getUTCDate() + 1); const w = d.getUTCDay(); if (w !== 0 && w !== 6) n++; } return d.toISOString().slice(0, 10); };
const plusMois = m => { const d = new Date(); d.setMonth(d.getMonth() + m); return d.toISOString().slice(0, 10); };
const fonctionDe = poste => { const p = norm(poste); if (/image|artisti|creati/.test(p)) return 'Image'; if (/brand|marque/.test(p)) return 'Brand'; if (/digital|innovation|numerique/.test(p)) return 'Digital'; if (/communication|comms|presse|pr /.test(p + ' ')) return 'Communication'; if (/marketing|cmo|managing director|directeur general|directrice generale|general manager/.test(p)) return 'Marketing'; return 'Autre'; };
const ANGLES = { Image: 'Cohérence des codes, qualité de la direction créative', Marketing: "Impact business d'une campagne, rythme de production", Brand: 'Plateforme de marque, repositionnement', Digital: 'IA générative maîtrisée au service du désir', Communication: 'Éditorial, prises de parole, activations' };
const TONS = { 'mode & maroquinerie': "élégant, tourné vers l'image et le savoir-faire", 'joaillerie & horlogerie': 'raffiné, précis, patrimoine et exception', 'beaute & parfumerie': 'sensoriel, moderne', 'vins & spiritueux': 'chaleureux, art de recevoir', 'hospitality & lifestyle': 'chaleureux, art de recevoir', 'lifestyle premium': 'élégant et sobre', 'prescripteurs': 'direct et confraternel, toujours au vouvoiement' };
const gem = j => { try { return JSON.parse(j.candidates?.[0]?.content?.parts?.[0]?.text); } catch (e) { return null; } };
const b64url = s => Buffer.from(s).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
const mime = (to, sujet, corps, extra = []) => b64url([...(to ? ['To: ' + to] : []), ...extra, 'Subject: =?UTF-8?B?' + Buffer.from(sujet).toString('base64') + '?=', 'MIME-Version: 1.0', 'Content-Type: text/plain; charset="UTF-8"', 'Content-Transfer-Encoding: base64', '', Buffer.from(corps).toString('base64')].join('\r\n'));

const carte = $('Carte Pipedrive').first().json; const cfg = $('CONFIG').first().json; const K = carte.deal, KP = carte.person;
const deals = ($('Toutes les affaires').first().json.data || []).filter(d => d.pipeline_id === carte.pipeline_id);
const persons = ($('Toutes les personnes').first().json.data || []);
const nomEtape = Object.fromEntries(Object.entries(carte.stage).map(([k, v]) => [v, k]));
const debutSemaine = (() => { const d = new Date(); const w = (d.getUTCDay() + 6) % 7; d.setUTCDate(d.getUTCDate() - w); return d.toISOString().slice(0, 10); })();
const envoyes = deals.filter(d => (val(d, K['Date premier envoi']) || '') >= debutSemaine).length;
const places = Math.max(0, cfg.plafond_hebdo - envoyes);
const candidats = deals.filter(d => d.status === 'open' && d.stage_id === carte.stage['À qualifier'] && /^(A|B)/.test(val(d, K['Niveau']) || '') && norm(val(d, K['Activer'])) !== 'oui')
  .sort((a, b) => Number(val(b, K['Score Résonance']) || 0) - Number(val(a, K['Score Résonance']) || 0));
const ligne = d => '- ' + (val(d, K['Niveau']) || '') + ' · ' + (val(d, K['Score Résonance']) || '?') + '/100 · ' + (d.org_name || d.org_id?.name || '') + ' · ' + (d.person_name || d.person_id?.name || 'contact à identifier') + ' — ' + (val(d, K['Motif du score']) || '');
const texte = ['Arbitrage du lundi · Résonance', '', 'Plafond : ' + cfg.plafond_hebdo + ' premiers messages par semaine · déjà envoyés cette semaine : ' + envoyes + ' · places disponibles : ' + places, '',
  'Prospects proposés (niveaux A puis B, par score) :', ...(candidats.length ? candidats.slice(0, 60).map(ligne) : ['Aucun prospect A ou B en attente.']), '',
  'Pour activer un prospect : dans Pipedrive, mettre le champ « Activer » à « Oui ». L\'agent 4 prépare alors le brouillon.',
  'Pour corriger un score : modifier les champs, noter le motif en note, puis vider « Score Résonance ».', '', 'En pièces jointes : export de secours des affaires et liste d\'opposition.'].join('\n');
const csv = rows => rows.map(r => r.map(c => '"' + String(c ?? '').replace(/"/g, '""') + '"').join(';')).join('\r\n');
const cols = ['Type de signal', 'URL source', 'Date de publication', 'Catégorie', 'Score Résonance', 'Niveau', 'Motif du score', 'Angle', 'Preuve A&L', 'Fait vérifié', 'Date premier envoi', 'Nb relances', 'Motif de refus', 'Date de réactivation', 'Fin de conservation'];
const export1 = '﻿' + csv([['ID', 'Titre', 'Organisation', 'Contact', 'Étape', 'Statut', ...cols], ...deals.map(d => [d.id, d.title, d.org_name || d.org_id?.name, d.person_name || d.person_id?.name, nomEtape[d.stage_id] || d.stage_id, d.status, ...cols.map(c => val(d, K[c]))])]);
const opp = persons.filter(p => norm(val(p, KP['Opposition'])).startsWith('oui'));
const export2 = '﻿' + csv([['ID', 'Nom', 'Email', 'Opposition'], ...opp.map(p => [p.id, p.name, (p.email || []).map(e => e.value).join(' '), val(p, KP['Opposition'])])]);
const to = cfg.emails_fondatrices || $('Profil Gmail').first().json.emailAddress;
const b = 'resonance' + Date.now();
const part = (name, data) => ['--' + b, 'Content-Type: text/csv; charset="UTF-8"; name="' + name + '"', 'Content-Disposition: attachment; filename="' + name + '"', 'Content-Transfer-Encoding: base64', '', Buffer.from(data).toString('base64')].join('\r\n');
const raw = b64url(['To: ' + to, 'Subject: =?UTF-8?B?' + Buffer.from('Résonance · Arbitrage du lundi et export du ' + today()).toString('base64') + '?=', 'MIME-Version: 1.0', 'Content-Type: multipart/mixed; boundary="' + b + '"', '',
  '--' + b, 'Content-Type: text/plain; charset="UTF-8"', 'Content-Transfer-Encoding: base64', '', Buffer.from(texte).toString('base64'), part('resonance_affaires_' + today() + '.csv', export1), part('resonance_opposition_' + today() + '.csv', export2), '--' + b + '--'].join('\r\n'));
return [{ json: { raw, candidats: candidats.length, places } }];
